/**
 * Complete every source-preview close path with the same transient cleanup.
 *
 * Bootstrap 4, Bootstrap 5 and the local fallback do not share one event
 * implementation. Keeping the cleanup here ensures Escape, backdrop, header
 * close and the fallback all invalidate an in-flight request and return focus
 * only once.
 *
 * @param {HTMLElement} modal Source-preview modal.
 * @returns {void}
 */
function localCourseBannerBuilderFinishSourceChainPreviewClose(modal) {
    if (!modal || modal.dataset.sourceChainPreviewFocusReturned === '1') {
        return;
    }
    modal.dataset.sourceChainPreviewFocusReturned = '1';
    modal.dataset.sourceChainPreviewRequest = '';
    modal.classList.remove('is-loading', 'is-easyedu-animating');
    var body = modal.querySelector('[data-source-chain-preview-modal-body="1"]');
    if (body) {
        body.classList.remove('is-loading');
        body.setAttribute('aria-busy', 'false');
    }
    var opener = modal.localCourseBannerBuilderSourceChainPreviewOpener;
    if (opener && document.contains(opener)) {
        opener.classList.add('is-focus-returned');
        opener.focus();
        opener.addEventListener('blur', function clearReturnedFocus() {
            opener.classList.remove('is-focus-returned');
        }, {once: true});
    }
}

/**
 * Load a configured source into the readonly source-preview modal.
 *
 * @param {HTMLElement} button Preview trigger.
 * @returns {void}
 */
function localCourseBannerBuilderShowSourceChainPreview(button) {
    var url = button ? button.getAttribute('data-preview-url') : '';
    var editUrl = button ? button.getAttribute('data-edit-url') : '';
    var editLabel = button ? button.getAttribute('data-edit-label') : '';
    var previewTitle = button ? button.getAttribute('data-preview-title') : '';
    var previewEyebrow = button ? button.getAttribute('data-preview-eyebrow') : '';
    var closeLabel = button ? button.getAttribute('data-close-label') : '';
    if (!url) {
        return;
    }
    var modal = localCourseBannerBuilderEnsureSourceChainPreviewModal();
    var body = modal.querySelector('[data-source-chain-preview-modal-body="1"]');
    var footer = modal.querySelector('[data-source-chain-preview-modal-footer="1"]');
    var title = modal.querySelector('.local-course-banner-builder-source-chain-preview-modal-title');
    var eyebrow = modal.querySelector('.local-course-banner-builder-source-chain-preview-modal-eyebrow');
    var close = modal.querySelector('.local-course-banner-builder-source-chain-preview-modal__close');
    if (title) {
        title.textContent = previewTitle || localCourseBannerBuilderGetJsString('sourcechainpreviewtitle', 'Source preview');
    }
    if (eyebrow) {
        eyebrow.textContent = previewEyebrow || 'Course Banner Builder';
    }
    if (close && closeLabel) {
        close.setAttribute('aria-label', closeLabel);
    }
    modal.localCourseBannerBuilderSourceChainPreviewOpener = button;
    var requestToken = String(Date.now()) + Math.random();
    modal.dataset.sourceChainPreviewRequest = requestToken;
    modal.dataset.sourceChainPreviewFocusReturn = '1';
    modal.dataset.sourceChainPreviewFocusReturned = '0';
    if (!modal.dataset.sourceChainPreviewFocusBound) {
        var finishClose = function() {
            localCourseBannerBuilderFinishSourceChainPreviewClose(modal);
        };
        modal.addEventListener('hidden.bs.modal', finishClose);
        if (typeof window.jQuery !== 'undefined') {
            window.jQuery(modal).on('hidden.bs.modal', finishClose);
        }
        modal.dataset.sourceChainPreviewFocusBound = '1';
    }
    if (body) {
        modal.classList.add('is-loading');
        body.classList.add('is-loading');
        body.setAttribute('aria-busy', 'true');
        body.removeAttribute('tabindex');
        body.innerHTML = '<div class="loading-icon icon-no-margin" role="status">' +
            '<span class="sr-only">' + localCourseBannerBuilderGetJsString('loading', 'Loading') + '</span></div>';
    }
    if (footer) {
        footer.innerHTML = '';
    }
    localCourseBannerBuilderShowModal(modal);
    fetch(url, {
        credentials: 'same-origin',
        headers: {'X-Requested-With': 'XMLHttpRequest'}
    }).then(function (response) {
        if (!response.ok) {
            throw new Error(localCourseBannerBuilderGetJsString(
                'unabletoloadsourcepreview',
                'Unable to load source preview'
            ));
        }
        return response.text();
    }).then(function (html) {
        if (modal.dataset.sourceChainPreviewRequest !== requestToken) {
            return;
        }
        var parser = new DOMParser();
        var doc = parser.parseFromString(html, 'text/html');
        var panel = doc.querySelector('[data-source-visual-editor="1"]');
        if (!body) {
            return;
        }
        modal.classList.remove('is-loading');
        body.classList.remove('is-loading');
        body.setAttribute('aria-busy', 'false');
        body.removeAttribute('tabindex');
        if (!panel) {
            var unavailableMessage = document.createElement('p');
            unavailableMessage.className = 'local-course-banner-builder-source-chain-preview-feedback mb-0';
            unavailableMessage.textContent = localCourseBannerBuilderGetJsString(
                'previewunavailable',
                'Preview unavailable.'
            );
            body.innerHTML = '';
            body.appendChild(unavailableMessage);
            body.setAttribute('tabindex', '-1');
            body.focus();
            return;
        }
        Array.prototype.slice.call(panel.querySelectorAll(
            '.local-course-banner-builder-source-preview-controls,' +
            '.local-course-banner-builder-source-preview-primary-actions,' +
            '.local-course-banner-builder-source-preview-bottom-row,' +
            '.local-course-banner-builder-source-preview-filmstrip,' +
            'form'
        )).forEach(function (node) {
            node.remove();
        });
        panel.setAttribute('data-source-preview-readonly', '1');
        panel.classList.add('local-course-banner-builder-source-preview-readonly');
        body.innerHTML = '';
        body.appendChild(document.importNode(panel, true));
        if (editUrl && footer) {
            var actionBar = document.createElement('div');
            actionBar.className = 'local-course-banner-builder-source-chain-preview-actions';
            var editButton = document.createElement('a');
            editButton.className = 'btn btn-primary local-course-banner-builder-source-preview-button';
            editButton.href = editUrl;
            var editIcon = document.createElement('i');
            editIcon.className = 'icon fa fa-pen fa-fw';
            editIcon.setAttribute('aria-hidden', 'true');
            var editText = document.createElement('span');
            editText.textContent = editLabel || localCourseBannerBuilderGetJsString('editsourcebutton', 'Edit source');
            editButton.appendChild(editIcon);
            editButton.appendChild(editText);
            actionBar.appendChild(editButton);
            footer.appendChild(actionBar);
        }
        localCourseBannerBuilderInitSourceVisualEditor(body);
        localCourseBannerBuilderInitPopovers(body);
    }).catch(function (error) {
        if (modal.dataset.sourceChainPreviewRequest !== requestToken) {
            return;
        }
        if (body) {
            modal.classList.remove('is-loading');
            body.classList.remove('is-loading');
            body.setAttribute('aria-busy', 'false');
            body.innerHTML = '';
            var errorMessage = document.createElement('p');
            errorMessage.className = 'local-course-banner-builder-source-chain-preview-feedback ' +
                'local-course-banner-builder-source-chain-preview-feedback--error mb-0';
            errorMessage.textContent = error.message || localCourseBannerBuilderGetJsString(
                'unabletoloadsourcepreview',
                'Unable to load source preview'
            );
            body.appendChild(errorMessage);
            body.setAttribute('tabindex', '-1');
            body.focus();
        }
    });
}

