var localCourseBannerBuilderAccordionSequence = 0;

/**
 * Finish every active CCB accordion within a scope before its layout changes.
 *
 * @param {HTMLElement|Document} scope Accordion scope.
 * @returns {void}
 */
function localCourseBannerBuilderFinishActiveAccordions(scope) {
    Array.prototype.slice.call((scope || document).querySelectorAll([
        'details.local-course-banner-builder-upload-accordion',
        'details.local-course-banner-builder-advanced-accordion',
        'details.local-course-banner-builder-section',
        'details.local-course-banner-builder-layer-details-accordion'
    ].join(','))).forEach(function(details) {
        if (details.dataset.accordionMotionActive !== '1') {
            return;
        }
        var content = details.querySelector(':scope > .local-course-banner-builder-accordion-content, ' +
            ':scope > .local-course-banner-builder-layer-details-accordion-content');
        if (content) {
            Motion.finish(content);
        }
    });
}

/**
 * Apply the final native and ARIA state for the latest accordion intent.
 *
 * @param {HTMLDetailsElement} details Accordion disclosure.
 * @param {HTMLElement} summary Accordion trigger.
 * @param {HTMLElement} content Accordion content wrapper.
 * @param {boolean} opening Whether the final state is open.
 * @returns {void}
 */
function localCourseBannerBuilderSetAccordionSettledState(details, summary, content, opening) {
    if (opening) {
        details.setAttribute('open', 'open');
        content.hidden = false;
    } else {
        details.removeAttribute('open');
        content.hidden = true;
    }
    summary.setAttribute('aria-expanded', opening ? 'true' : 'false');
    delete details.dataset.accordionMotionActive;
    delete details.dataset.accordionTargetOpen;
    delete details.dataset.accordionTransitionId;
}

function localCourseBannerBuilderEnhanceAccordions(root) {
    Array.prototype.slice.call((root || document).querySelectorAll([
        'details.local-course-banner-builder-upload-accordion',
        'details.local-course-banner-builder-advanced-accordion',
        'details.local-course-banner-builder-section',
        'details.local-course-banner-builder-layer-details-accordion'
    ].join(','))).forEach(function (details) {
        var summary = details.querySelector(':scope > summary');
        if (!summary) {
            return;
        }
        var content = details.querySelector(':scope > .local-course-banner-builder-accordion-content, ' +
            ':scope > .local-course-banner-builder-layer-details-accordion-content');
        if (!content) {
            content = document.createElement('div');
            content.className = 'local-course-banner-builder-accordion-content';
            var child = summary.nextSibling;
            while (child) {
                var next = child.nextSibling;
                content.appendChild(child);
                child = next;
            }
            details.appendChild(content);
        }
        if (!content.id) {
            localCourseBannerBuilderAccordionSequence += 1;
            content.id = 'local-course-banner-builder-accordion-content-' +
                String(localCourseBannerBuilderAccordionSequence);
        }
        summary.setAttribute('aria-controls', content.id);
        summary.setAttribute('aria-expanded', details.hasAttribute('open') ? 'true' : 'false');
        content.hidden = !details.hasAttribute('open');
        var usesCssChevron = details.classList.contains('local-course-banner-builder-layer-details-accordion');
        var icon = summary.querySelector('[data-accordion-chevron="1"], [data-local-details-toggle-icon="1"], .icons-collapse-expand');
        if (!icon && !usesCssChevron) {
            icon = document.createElement('span');
            icon.setAttribute('data-accordion-chevron', '1');
            icon.setAttribute('aria-hidden', 'true');
            icon.textContent = '';
            var firstChild = summary.firstChild;
            summary.insertBefore(icon, firstChild);
        }
        if (icon) {
            icon.setAttribute('data-accordion-chevron', '1');
            icon.setAttribute('aria-hidden', 'true');
            icon.className = 'btn btn-icon me-2 icons-collapse-expand local-course-banner-builder-collapse-icon';
            if (!icon.querySelector('.expanded-icon')) {
                icon.innerHTML = '<span class="expanded-icon icon-no-margin p-2"><i class="icon fa fa-chevron-down fa-fw" aria-hidden="true"></i></span>' +
                    '<span class="collapsed-icon icon-no-margin p-2"><i class="icon fa fa-chevron-right fa-fw" aria-hidden="true"></i></span>';
            }
            icon.removeAttribute('style');
            icon.classList.toggle('collapsed', !details.hasAttribute('open'));
        }
        if (!details.dataset.chevronBound) {
            details.addEventListener('toggle', function () {
                var toggleIcon = summary.querySelector('[data-accordion-chevron="1"], [data-local-details-toggle-icon="1"], .icons-collapse-expand');
                var targetOpen = details.dataset.accordionTargetOpen;
                var isExpanded = targetOpen === undefined ? details.hasAttribute('open') : targetOpen === '1';
                if (toggleIcon) {
                    toggleIcon.style.removeProperty('transform');
                    toggleIcon.classList.toggle('collapsed', !isExpanded);
                }
                summary.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
                if (!details.dataset.accordionMotionActive) {
                    content.hidden = !details.hasAttribute('open');
                }
            });
            details.dataset.chevronBound = '1';
        }
        if (!details.dataset.accordionMotionBound) {
            summary.addEventListener('click', function (event) {
                event.preventDefault();
                var targetOpen = details.dataset.accordionTargetOpen;
                var opening = targetOpen === undefined ? !details.hasAttribute('open') : targetOpen !== '1';
                var transitionId = String((parseInt(details.dataset.accordionTransitionId || '0', 10) || 0) + 1);
                details.dataset.accordionMotionActive = '1';
                details.dataset.accordionTargetOpen = opening ? '1' : '0';
                details.dataset.accordionTransitionId = transitionId;
                summary.setAttribute('aria-expanded', opening ? 'true' : 'false');
                if (icon) {
                    icon.classList.toggle('collapsed', !opening);
                }
                if (opening) {
                    details.setAttribute('open', 'open');
                    // Motion.expand must observe the collapsed zero-height
                    // state before it reveals and measures the content. If we
                    // unhide first, its start and end heights are identical,
                    // so opening appears instantaneous while closing still
                    // animates.
                    Motion.expand(content).then(function () {
                        if (details.dataset.accordionTransitionId !== transitionId) {
                            return;
                        }
                        localCourseBannerBuilderSetAccordionSettledState(details, summary, content, true);
                    });
                    return;
                }
                Motion.collapse(content).then(function () {
                    if (details.dataset.accordionTransitionId !== transitionId) {
                        return;
                    }
                    localCourseBannerBuilderSetAccordionSettledState(details, summary, content, false);
                });
            });
            details.dataset.accordionMotionBound = '1';
        }
    });
}

var localCourseBannerBuilderLayerModalRequestCache = {};
var localCourseBannerBuilderLayerModalCacheLifetime = 30000;

function localCourseBannerBuilderRequestLayerModal(url) {
    var now = Date.now();
    var cached = localCourseBannerBuilderLayerModalRequestCache[url];
    if (cached && cached.expires > now) {
        return cached.promise;
    }

    var request = fetch(url, {
        credentials: 'same-origin',
        headers: {'X-Requested-With': 'XMLHttpRequest'}
    }).then(function (response) {
        if (!response.ok) {
            throw new Error(localCourseBannerBuilderGetJsString('unabletoloadlayerform', ''));
        }
        return response.text();
    });
    localCourseBannerBuilderLayerModalRequestCache[url] = {
        expires: now + localCourseBannerBuilderLayerModalCacheLifetime,
        promise: request
    };
    request.catch(function () {
        delete localCourseBannerBuilderLayerModalRequestCache[url];
    });
    return request;
}

function localCourseBannerBuilderPrefetchLayerModal(url) {
    if (url) {
        localCourseBannerBuilderRequestLayerModal(url);
    }
}

function localCourseBannerBuilderShowLayerModalLoading(modal, requestId) {
    if (!modal) {
        return;
    }
    var body = modal.querySelector('.modal-body');
    if (!body) {
        return;
    }
    var status = document.createElement('div');
    status.className = 'local-course-banner-builder-layer-modal-loading';
    status.setAttribute('role', 'status');
    var title = modal.querySelector('.modal-title');
    if (title) {
        status.setAttribute('aria-label', title.textContent.trim());
    }
    var spinner = document.createElement('span');
    spinner.className = 'spinner-border text-primary';
    spinner.setAttribute('aria-hidden', 'true');
    status.appendChild(spinner);
    body.replaceChildren(status);
    modal.dataset.layerModalLoading = '1';
    modal.dataset.layerModalRequest = requestId;
    localCourseBannerBuilderShowModal(modal);
}

function localCourseBannerBuilderRefreshLoadedLayerModal(modal) {
    var form = modal ? modal.querySelector('form.mform') : null;
    window.requestAnimationFrame(function () {
        localCourseBannerBuilderRefreshCurrentPreviewLayer(form);
        localCourseBannerBuilderSyncBorderPreview(form);
        localCourseBannerBuilderSyncContextPreviewVisibility(form);
        window.requestAnimationFrame(function () {
            localCourseBannerBuilderSyncBorderPreview(form);
        });
    });
}

function localCourseBannerBuilderLoadLayerModal(url, modalId) {
    if (!url) {
        return;
    }
    var requestId = String(Date.now()) + '-' + String(Math.random());
    var requestedModal = modalId ? document.getElementById(modalId) : null;
    if (requestedModal) {
        localCourseBannerBuilderShowLayerModalLoading(requestedModal, requestId);
    }

    localCourseBannerBuilderRequestLayerModal(url).then(function (response) {
        var html = response;
        var parser = new DOMParser();
        var doc = parser.parseFromString(html, 'text/html');
        var fetchedmodal = localCourseBannerBuilderFindFetchedLayerModal(doc);
        if (!fetchedmodal) {
            throw new Error(localCourseBannerBuilderGetJsString('fetchedmodalnotfound', ''));
        }

        if (fetchedmodal.id === 'local-course-banner-builder-add-layer-modal') {
            throw new Error(localCourseBannerBuilderGetJsString('unexpectedcreatemodalreturned', ''));
            return;
        }

        var targetmodal = document.getElementById(fetchedmodal.id);
        if (!targetmodal) {
            throw new Error(localCourseBannerBuilderGetJsString('targetmodalnotfound', ''));
        }
        if (requestedModal && targetmodal !== requestedModal) {
            throw new Error(localCourseBannerBuilderGetJsString('targetmodalnotfound', ''));
        }
        if (requestedModal && targetmodal.dataset.layerModalRequest !== requestId) {
            return;
        }
        if (!requestedModal) {
            targetmodal.dataset.layerModalRequest = requestId;
        }

        var fetchedtitle = fetchedmodal.querySelector('.modal-title');
        var fetchedbody = fetchedmodal.querySelector('.modal-body');
        var targettitle = targetmodal.querySelector('.modal-title');
        var targetbody = targetmodal.querySelector('.modal-body');
        if (!fetchedbody || !targetbody) {
            throw new Error(localCourseBannerBuilderGetJsString('modalbodynotfound', ''));
        }

        if (fetchedtitle && targettitle) {
            targettitle.textContent = fetchedtitle.textContent;
        }
        targetbody.innerHTML = fetchedbody.innerHTML;

        var form = targetbody.querySelector('form.mform');
        if (form && fetchedmodal.id === 'local-course-banner-builder-edit-image-layer-modal') {
            form.setAttribute('data-layer-modal-mode', 'editimage');
            var hasExistingImage = form.querySelector('#id_hasexistingimage');
            if (hasExistingImage) {
                hasExistingImage.value = '1';
            }
        }
        if (form && fetchedmodal.id === 'local-course-banner-builder-edit-border-layer-modal') {
            form.setAttribute('data-layer-modal-mode', 'editborder');
            form.setAttribute('data-edit-border-locked', '1');
            var currentIsBorderLayer = form.querySelector('#id_currentisborderlayer');
            if (currentIsBorderLayer) {
                currentIsBorderLayer.value = '1';
            }
            var borderToggle = form.querySelector(
                '[data-border-toggle="1"][type="checkbox"], [data-border-toggle="1"][type="hidden"]'
            );
            if (borderToggle) {
                if (borderToggle.type === 'checkbox') {
                    borderToggle.checked = true;
                    borderToggle.disabled = true;
                    borderToggle.setAttribute('aria-disabled', 'true');
                } else {
                    borderToggle.value = '1';
                }
            }
            var sidesValue = form.querySelector('#id_bordersidesvalue');
            if (sidesValue) {
                form.dataset.borderSidesValue = sidesValue.value;
            }
        }
        if (form && fetchedmodal.id === 'local-course-banner-builder-edit-overlay-layer-modal') {
            form.setAttribute('data-layer-modal-mode', 'editoverlay');
            var currentIsOverlayLayer = form.querySelector('#id_currentisoverlaylayer');
            if (currentIsOverlayLayer) {
                currentIsOverlayLayer.value = '1';
            }
            var overlayToggle = localCourseBannerBuilderGetOverlayToggle(form);
            if (overlayToggle) {
                if (overlayToggle.type === 'checkbox') {
                    overlayToggle.checked = true;
                    overlayToggle.disabled = true;
                    overlayToggle.setAttribute('aria-disabled', 'true');
                } else {
                    overlayToggle.value = '1';
                }
            }
            localCourseBannerBuilderSetSelectedLayerType(form, 'overlay');
        }

        localCourseBannerBuilderSafelyPrepareDynamicLayerModal(targetmodal);
        targetmodal.removeAttribute('data-layer-modal-loading');
        targetmodal.removeAttribute('data-layer-modal-request');
        if (!targetmodal.classList.contains('show')) {
            localCourseBannerBuilderShowModal(targetmodal);
        }
        localCourseBannerBuilderRefreshLoadedLayerModal(targetmodal);
    }).catch(function (error) {
        window.console.error(error);
        if (requestedModal && requestedModal.dataset.layerModalRequest === requestId) {
            requestedModal.removeAttribute('data-layer-modal-loading');
            requestedModal.removeAttribute('data-layer-modal-request');
            localCourseBannerBuilderHideModal(requestedModal);
        }
    });
}

function localCourseBannerBuilderGetStickyLayoutTop(element) {
    var top = 0;
    var current = element;
    while (current) {
        top += current.offsetTop || 0;
        current = current.offsetParent;
    }
    return top;
}

/**
 * Find the scroll container that actually moves the administration page.
 * Moodle may keep the document at scrollY=0 while an inner layout shell
 * owns the vertical scroll position.
 *
 * @param {HTMLElement} element Sticky holder.
 * @return {Element} Scroll container or the document scrolling element.
 */
function localCourseBannerBuilderGetStickyScrollContainer(element) {
    var current = element ? element.parentElement : null;
    while (current && current !== document.body) {
        var style = window.getComputedStyle(current);
        var scrollable = /(auto|scroll|overlay)/.test(style.overflowY) &&
            current.scrollHeight > current.clientHeight + 1;
        if (scrollable) {
            return current;
        }
        current = current.parentElement;
    }
    return document.scrollingElement || document.documentElement;
}

/**
 * Read the current scroll position for a document or nested scroll shell.
 *
 * @param {Element} container Scroll container.
 * @return {number} Current vertical scroll offset.
 */
function localCourseBannerBuilderGetStickyScrollTop(container) {
    if (!container || container === document.scrollingElement ||
            container === document.documentElement || container === document.body) {
        return window.scrollY || document.documentElement.scrollTop || 0;
    }
    return container.scrollTop || 0;
}

/**
 * Return the viewport top of a holder's original anchor.
 *
 * @param {HTMLElement} holder Sticky holder.
 * @param {Element} container Scroll container.
 * @param {number} anchorContentTop Anchor position in the container content.
 * @return {number} Anchor viewport top.
 */
function localCourseBannerBuilderGetStickyAnchorViewportTop(holder, container, anchorContentTop) {
    var scrollTop = localCourseBannerBuilderGetStickyScrollTop(container);
    if (!container || container === document.scrollingElement ||
            container === document.documentElement || container === document.body) {
        return anchorContentTop - scrollTop;
    }
    return container.getBoundingClientRect().top + anchorContentTop - scrollTop;
}

/**
 * Reserve the live Moodle block-drawer toggle while the selected-source tray
 * occupies the viewport. The toggle is theme-owned, so measure its current
 * viewport footprint instead of assuming a fixed offset.
 *
 * @return {number} Right-side space in CSS pixels.
 */
function localCourseBannerBuilderGetStickyRightDrawerSpace() {
    var toggle = document.querySelector('.drawer-toggles .drawer-right-toggle');
    if (!toggle) {
        return 0;
    }
    var style = window.getComputedStyle(toggle);
    var rect = toggle.getBoundingClientRect();
    var viewportWidth = document.documentElement.clientWidth || window.innerWidth;
    if (style.display === 'none' || style.visibility === 'hidden' || rect.width <= 0 ||
            rect.right <= 0 || rect.left >= viewportWidth) {
        return 0;
    }
    return Math.min(viewportWidth, Math.max(0, viewportWidth - rect.left + 28));
}

/**
 * Return the placeholder that preserves the selected-source holder's natural
 * place in the administration layout while its live control is in the body
 * portal.
 *
 * @return {HTMLElement|null} Sticky placeholder, when present.
 */
function localCourseBannerBuilderGetStickyPlaceholder() {
    return document.getElementById('local-course-banner-builder-selected-source-sticky-placeholder');
}

/**
 * Restore the selected-source holder to its source-layout position.
 *
 * @param {HTMLElement} holder Sticky holder.
 * @param {HTMLElement} header Sticky header.
 */
function localCourseBannerBuilderRestoreStickyHeader(holder, header) {
    var placeholder = localCourseBannerBuilderGetStickyPlaceholder();
    if (holder.dataset.stickyState === 'inline' && holder.dataset.stickyPortal !== '1') {
        return;
    }
    if (holder.dataset.stickyPortal === '1' && placeholder && placeholder.parentNode) {
        placeholder.parentNode.replaceChild(holder, placeholder);
    }
    holder.classList.remove('focus-navigation-buttons-holder--floating');
    holder.classList.remove('local-course-banner-builder-selected-source-sticky-holder--portal');
    header.classList.remove('focus-navigation-buttons--floating');
    delete holder.dataset.stickyPortal;
    holder.style.left = '';
    holder.style.right = '';
    holder.style.width = '';
    holder.style.top = '';
    holder.style.bottom = '';
    holder.style.minHeight = '';
    header.style.left = '';
    header.style.right = '';
    header.style.width = '';
    header.style.top = '';
    header.style.setProperty('--local-course-banner-builder-sticky-header-right-space', '0px');
    holder.dataset.stickyState = 'inline';
    if (document.body.style.getPropertyValue('--local-course-banner-builder-sticky-header-space') !== '0px') {
        document.body.style.setProperty('--local-course-banner-builder-sticky-header-space', '0px');
    }
}

/**
 * Move the selected-source holder to the body while it is sticky. The portal
 * avoids transformed administration containers constraining position: fixed
 * and lets the tray use the actual viewport width.
 *
 * @param {HTMLElement} holder Sticky holder.
 * @param {HTMLElement} header Sticky header.
 * @param {number} top Viewport top offset below the Moodle navigation.
 * @param {number} viewportWidth Available viewport width.
 */
function localCourseBannerBuilderFloatStickyHeader(holder, header, top, viewportWidth) {
    var placeholder = localCourseBannerBuilderGetStickyPlaceholder();
    if (holder.dataset.stickyPortal !== '1') {
        var holderStyle = window.getComputedStyle(holder);
        placeholder = document.createElement('div');
        placeholder.id = 'local-course-banner-builder-selected-source-sticky-placeholder';
        placeholder.className = 'local-course-banner-builder-selected-source-sticky-placeholder';
        placeholder.setAttribute('aria-hidden', 'true');
        // Preserve the natural block footprint before the floating class
        // removes its top margin. Without these margins the replacement shifts
        // the threshold sentinel and can make the tray restore immediately.
        placeholder.style.marginTop = holderStyle.marginTop;
        placeholder.style.marginBottom = holderStyle.marginBottom;
        holder.parentNode.insertBefore(placeholder, holder);
        document.body.appendChild(holder);
        holder.dataset.stickyPortal = '1';
    }
    if (placeholder) {
        placeholder.style.height = header.offsetHeight + 'px';
    }
    holder.classList.add('focus-navigation-buttons-holder--floating');
    holder.classList.add('local-course-banner-builder-selected-source-sticky-holder--portal');
    header.classList.add('focus-navigation-buttons--floating');
    holder.style.left = '0px';
    holder.style.right = '';
    holder.style.width = viewportWidth + 'px';
    holder.style.top = top + 'px';
    holder.style.bottom = 'auto';
    holder.style.minHeight = '';
    header.style.left = '';
    header.style.right = '';
    header.style.width = '100%';
    header.style.top = '';
    header.style.setProperty(
        '--local-course-banner-builder-sticky-header-right-space',
        localCourseBannerBuilderGetStickyRightDrawerSpace() + 'px'
    );
    holder.dataset.stickyState = 'stuck';
    var stickySpace = header.offsetHeight + 'px';
    // The portal layout can increase the tray height (notably when narrow
    // screens stack the source title and Deselect action). Update the
    // placeholder only after those classes/styles are live, otherwise its
    // temporary shorter footprint moves its own threshold anchor.
    if (placeholder) {
        placeholder.style.height = stickySpace;
    }
    if (document.body.style.getPropertyValue('--local-course-banner-builder-sticky-header-space') !== stickySpace) {
        document.body.style.setProperty('--local-course-banner-builder-sticky-header-space', stickySpace);
    }
}

function localCourseBannerBuilderSyncStickyHeader() {
    var holder = document.querySelector('.local-course-banner-builder-selected-source-sticky-holder');
    var header = document.querySelector('.local-course-banner-builder-selected-source-sticky');
    var breadcrumbnav = document.querySelector('#page-header .page-header-nav');
    if (breadcrumbnav) {
        var breadcrumbHeight = breadcrumbnav.offsetHeight + 'px';
        if (document.body.style.getPropertyValue('--local-course-banner-builder-breadcrumb-height') !== breadcrumbHeight) {
            document.body.style.setProperty('--local-course-banner-builder-breadcrumb-height', breadcrumbHeight);
        }
    }
    if (!holder || !header) {
        return;
    }
    // The CSS sticky rule is only a no-JavaScript fallback. Once the runtime
    // owns this holder, the explicit inline/stuck state below is its sole
    // positioning authority; native container sticky must not compete with
    // the body-level portal around the threshold.
    document.documentElement.dataset.localCourseBannerBuilderStickyRuntime = '1';
    // A four-pixel entry allowance absorbs Moodle's fractional scroll/layout
    // rounding at ordinary and native-zoom viewports. The larger release
    // offset below preserves a deliberate hysteresis band for upward scroll.
    var enterOffset = 4;
    var releaseOffset = 12;
    var isStuck = holder.dataset.stickyState === 'stuck' || holder.dataset.stickyPortal === '1';

    // Prefer the fixed Moodle navigation. #page-navbar can be a normal-flow
    // ancestor on some Boost layouts and then reports a scrolling, negative
    // viewport edge instead of the live navigation edge.
    var navbar = document.querySelector('.navbar.fixed-top') ||
        document.querySelector('header.fixed-top') ||
        document.querySelector('#page-header.fixed-top') ||
        document.querySelector('#page-navbar');
    var top = navbar ? Math.max(0, navbar.getBoundingClientRect().bottom) : 0;
    // Once the holder is portaled into body, its own rectangle is fixed. Its
    // placeholder stays in the original scroll layout, so it is the stable
    // threshold sentinel across nested Moodle scroll containers and restores.
    var placeholder = localCourseBannerBuilderGetStickyPlaceholder();
    var anchor = isStuck && holder.dataset.stickyPortal === '1' && placeholder ?
        placeholder : holder;
    var anchorViewportTop = anchor.getBoundingClientRect().top;
    var thresholdOffset = isStuck ?
        releaseOffset : enterOffset;
    var shouldFloat = Number.isFinite(anchorViewportTop) && anchorViewportTop <= top + thresholdOffset;
    if (!shouldFloat) {
        localCourseBannerBuilderRestoreStickyHeader(holder, header);
        return;
    }
    var viewportWidth = document.documentElement.clientWidth || window.innerWidth;
    localCourseBannerBuilderFloatStickyHeader(holder, header, top, viewportWidth);
}

function localCourseBannerBuilderRunInitStep(label, callback) {
    try {
        callback();
    } catch (error) {
        if (window.console && window.console.error) {
            window.console.error('Course banner builder init failed: ' + label, error);
        }
    }
}

